--
-- TOC entry 552 (class 1255 OID 18615)
-- Name: close_expired_opportunities(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_expired_opportunities() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Automatically open scheduled opportunities
    UPDATE opportunity_master
    SET
        application_status = 'Open',
        visible_to_students = true
    WHERE
        application_status = 'Upcoming'
        AND application_start_date IS NOT NULL
        AND application_start_date <= now();

    -- Automatically close expired opportunities
    UPDATE opportunity_master
    SET
        application_status = 'Closed',
        visible_to_students = false
    WHERE
        application_status = 'Open'
        AND application_end_date IS NOT NULL
        AND application_end_date < now();

END;
$$;


ALTER FUNCTION public.close_expired_opportunities() OWNER TO postgres;

