-- Name: normalize_enrollment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.normalize_enrollment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    NEW.enrollment_no :=
        regexp_replace(
            upper(trim(NEW.enrollment_no)),
            '[^A-Z0-9]',
            '',
            'g'
        );

    RETURN NEW;
END;
$$;


