--
-- TOC entry 568 (class 1255 OID 23611)
-- Name: populate_execution_round_participants(uuid, uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.populate_execution_round_participants(p_execution_id uuid, p_source_round_id uuid, p_target_round_id uuid, p_role_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
    v_inserted integer := 0;
begin

        execution_id,
        application_id,
        student_id
    )
    select distinct
        p_execution_id,
        participant.application_id,
        participant.student_id
    from recruitment_execution_participants participant
    join recruitment_execution_history history
      on history.execution_participant_id = participant.execution_participant_id
    join student_application_selected_roles selected_role
      on selected_role.application_id = participant.application_id
    where participant.execution_id = p_execution_id
      and history.execution_round_id = p_source_round_id
      and history.progression_status = 'SHORTLISTED'
      and (
            p_role_ids is null
            or cardinality(p_role_ids) = 0
            or selected_role.drive_role_id = any(p_role_ids)
      );

    get diagnostics v_inserted = row_count;

    return v_inserted;

end;
$$;


ALTER FUNCTION public.populate_execution_round_participants(p_execution_id uuid, p_source_round_id uuid, p_target_round_id uuid, p_role_ids uuid[]) OWNER TO postgres;

--
-- TOC entry 538 (class 1255 OID 17366)
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.rls_auto_enable() OWNER TO postgres;

--
-- TOC entry 567 (class 1255 OID 23599)
-- Name: save_round_transaction(uuid, uuid, integer, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_round_transaction(p_execution_id uuid, p_execution_round_id uuid, p_execution_revision integer, p_changed_by uuid, p_history_rows jsonb, p_next_round_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$declare
    v_saved_events integer := 0;
    v_progressed integer := 0;
begin

    ------------------------------------------------------------------------
    -- Attendance Review Validation
    ------------------------------------------------------------------------

    if exists (
        select 1
        from recruitment_execution_attendance_review
        where execution_round_id = p_execution_round_id
          and is_draft = true
          and absence_disposition = 'ALLOWED'
          and (
                absence_reason is null
                or btrim(absence_reason) = ''
          )
    ) then
        raise exception 'Allowed absence requires a reason.';
    end if;

    if exists (
        select 1
        from recruitment_execution_attendance_review
        where execution_round_id = p_execution_round_id
          and is_draft = true
          and restriction_override = true
          and (
                override_reason is null
                or btrim(override_reason) = ''
          )
    ) then
        raise exception 'Restriction override requires a reason.';
    end if;

    ------------------------------------------------------------------------
-- Progression Validation
------------------------------------------------------------------------

IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_history_rows)
    AS x(
        attendance_status text,
        gate_status text,
        progression_status text,
        absence_disposition text,
        restriction_override boolean
    )
    WHERE
        progression_status IN ('SHORTLISTED','SELECTED')
        AND
        (
            (
                attendance_status = 'ABSENT'
                AND COALESCE(absence_disposition,'UNALLOWED') <> 'ALLOWED'
            )
            OR
            (
                gate_status = 'RESTRICTED'
                AND COALESCE(restriction_override,false) = false
            )
        )
)
THEN
    RAISE EXCEPTION
    'Candidate cannot be progressed until attendance and restriction requirements are satisfied.';
END IF;

------------------------------------------------------------------------
-- Normalize History Payload
------------------------------------------------------------------------

p_history_rows :=
(
    SELECT jsonb_agg(
        jsonb_build_object(
            'execution_id', execution_id,
            'execution_round_id', execution_round_id,
            'execution_participant_id', execution_participant_id,
            'execution_revision', execution_revision,
            'history_revision', history_revision,

            'attendance_status', attendance_status,
            'gate_status', gate_status,
            'progression_status', progression_status,
            'remarks', remarks,

            'absence_disposition', absence_disposition,

            'absence_reason',
                CASE
                    WHEN absence_disposition = 'ALLOWED'
                    THEN absence_reason
                    ELSE NULL
                END,

            'restriction_override',
                COALESCE(restriction_override,false),

            'restriction_override_reason',
                CASE
                    WHEN COALESCE(restriction_override,false)
                    THEN restriction_override_reason
                    ELSE NULL
                END,

            'previous_history_id', previous_history_id,
            'changed_by', changed_by
        )
    )
    FROM jsonb_to_recordset(p_history_rows)
    AS x(
        execution_id uuid,
        execution_round_id uuid,
        execution_participant_id uuid,
        execution_revision integer,
        history_revision integer,

        attendance_status text,
        gate_status text,
        progression_status text,
        remarks text,

        absence_disposition text,
        absence_reason text,

        restriction_override boolean,
        restriction_override_reason text,

        previous_history_id uuid,
        changed_by uuid
    )
);


    ------------------------------------------------------------------------
    -- Immutable History
    ------------------------------------------------------------------------

    execution_id,
    execution_round_id,
    execution_participant_id,
    execution_revision,
    history_revision,
    attendance_status,
    gate_status,
    progression_status,
    remarks,

    absence_disposition,
    absence_reason,
    restriction_override,
    restriction_override_reason,

    previous_history_id,
    changed_by
)
 select
    x.execution_id,
    x.execution_round_id,
    x.execution_participant_id,
    x.execution_revision,
    x.history_revision,
    x.attendance_status::execution_attendance_status,
    x.gate_status::execution_gate_status,
    x.progression_status::execution_progression_status,
    x.remarks,

    x.absence_disposition::execution_absence_disposition,
    x.absence_reason,
    coalesce(x.restriction_override, false),
    x.restriction_override_reason,

    x.previous_history_id,
    x.changed_by
    from jsonb_to_recordset(p_history_rows)
  as x(
    execution_id uuid,
    execution_round_id uuid,
    execution_participant_id uuid,
    execution_revision integer,
    history_revision integer,

    attendance_status text,
    gate_status text,
    progression_status text,
    remarks text,

    absence_disposition text,
    absence_reason text,
    restriction_override boolean,
    restriction_override_reason text,

    previous_history_id uuid,
    changed_by uuid
);

    get diagnostics v_saved_events = row_count;

    ------------------------------------------------------------------------
    -- Consume Attendance Review Draft
    ------------------------------------------------------------------------

    delete
    from recruitment_execution_attendance_review
    where execution_round_id = p_execution_round_id
      and is_draft = true;

    ------------------------------------------------------------------------
    -- Existing Phase 1 output
    ------------------------------------------------------------------------

    return jsonb_build_object(
        'savedEvents',
        v_saved_events,
        'progressedParticipants',
        v_progressed
    );

end;$$;


ALTER FUNCTION public.save_round_transaction(p_execution_id uuid, p_execution_round_id uuid, p_execution_revision integer, p_changed_by uuid, p_history_rows jsonb, p_next_round_id uuid) OWNER TO postgres;

